function openAgentAssign(providerId,modelName){const p=(state.providers||[]).find(x=>x.id===providerId);$('#assign-model-label').textContent=(p?.name||'Провайдер')+' / '+modelName;$('#assign-agent-list').innerHTML=(state.agents||[]).map(a=>'<article class="provider-row"><div class="provider-main"><b>'+esc(a.name)+'</b><small>'+esc(a.role||'')+' · '+esc(a.model||'Модель не назначена')+'</small></div><button class="btn primary" data-assign-agent="'+esc(a.id)+'">Назначить</button></article>').join('')||'<div class="empty">Сначала создайте агента в разделе AI-агенты.</div>';$('#agent-assign-modal').hidden=false;document.querySelectorAll('[data-assign-agent]').forEach(b=>b.onclick=async()=>{try{await api('/providers/assign',{method:'POST',body:JSON.stringify({agent_id:b.dataset.assignAgent,provider_id:providerId,model:modelName})});await reload();$('#agent-assign-modal').hidden=true;render();toast('Модель назначена агенту')}catch(e){toast(e.message)}})}
