const ggufForm=$('#gguf-form');if(ggufForm)ggufForm.onsubmit=async e=>{e.preventDefault();const payload={id:$('#gguf-id').value,name:$('#gguf-name').value.trim(),kind:'file',format:'gguf',base_url:$('#gguf-path').value.trim(),n_ctx:Number($('#gguf-n-ctx').value||4096),n_gpu_layers:Number($('#gguf-n-gpu-layers').value??-1),temperature:Number($('#gguf-temperature').value??0.7),top_p:Number($('#gguf-top-p').value??0.9),repeat_penalty:Number($('#gguf-repeat-penalty').value??1.1)};try{await api('/providers',{method:'POST',body:JSON.stringify(payload)});$('#gguf-modal').hidden=true;state.modelsTab='file';await loadProviders();render();toast('Файловая модель сохранена')}catch(err){$('#gguf-form-status').innerHTML='<div class="notice warning">'+esc(err.message)+'</div>'}};
