const hfForm=$('#hf-search-form');const runHfSearch=async()=>{const query=String($('#hf-search-query')?.value||'').trim(),status=$('#hf-search-status'),results=$('#hf-search-results');if(!query){status.textContent='Введите запрос для поиска.';return}status.textContent='Поиск на Hugging Face…';results.innerHTML='';try{const response=await api('/models/search/hf?q='+encodeURIComponent(query)+'&limit=10');const items=response.items||[];status.textContent=items.length?'Найдено репозиториев: '+items.length:'GGUF-репозитории не найдены.';results.innerHTML=items.map(item=>'<article class="entity-row"><div class="entity-row-main"><div class="entity-row-heading"><b>'+esc(item.id)+'</b></div><p>Скачиваний: '+Number(item.downloads||0).toLocaleString('ru-RU')+' · Нравится: '+Number(item.likes||0).toLocaleString('ru-RU')+'</p><small>'+esc((item.tags||[]).slice(0,6).join(' · '))+'</small><div class="field" style="margin-top:10px"><label>Файл GGUF</label><select data-hf-file-for="'+esc(item.id)+'">'+(item.files||[]).map(file=>'<option value="'+esc(file)+'">'+esc(file)+'</option>').join('')+'</select></div></div><div class="entity-row-actions"><button class="btn primary" data-hf-download="'+esc(item.id)+'" '+(!(item.files||[]).length?'disabled':'')+'>Скачать и подключить</button></div></article>').join('')||'<div class="empty">Попробуйте другой запрос.</div>';document.querySelectorAll('[data-hf-download]').forEach(button=>button.onclick=async()=>{const repoId=button.dataset.hfDownload,select=document.querySelector('[data-hf-file-for="'+CSS.escape(repoId)+'"]'),filename=select?.value;if(!filename)return;button.disabled=true;button.textContent='Скачивание…';try{await api('/models/download',{method:'POST',body:JSON.stringify({repo_id:repoId,filename,n_gpu_layers:-1})});button.textContent='Установлено';button.classList.remove('primary');button.classList.add('secondary');state.modelsTab='file';await loadProviders();render();toast('Модель скачана и подключена')}catch(err){button.disabled=false;button.textContent='Скачать и подключить';status.textContent=err.message}})}catch(err){status.textContent=err.message}};
